            case 48: case 49:
                return { BDSP_LOC_NAMES_6_BY_LANGUAGE[displayLanguageIndex()], sizeof(BDSP_LOC_NAMES_6_EN) / sizeof(BDSP_LOC_NAMES_6_EN[0]) };
